// Shim minimal du runtime JSX automatique. zcompiler abaisse `<Badge x={1}/>`
// en `jsx(Badge, { x: 1 })` et INJECTE l'import de ce module ; il est donc une
// dependance reelle du projet, externe au bundle (specifier nu).
export const jsx = (type, props) => ({ type, props });
export const jsxs = jsx;
export const Fragment = 'fragment';
